{
  "name": "opencode-free-stack",
  "version": "0.1.0",
  "description": "Free-model stack for OpenCode: route requests to genuinely free models across providers, pace them to free-tier RPM limits, track daily quotas, and fall back automatically when one provider is empty.",
  "type": "module",
  "license": "MIT",
  "bin": {
    "ofs": "bin/ofs.js"
  },
  "exports": {
    ".": "./src/index.js",
    "./plugin": "./plugin/index.ts"
  },
  "engines": {
    "node": ">=20"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "free",
    "free-tier",
    "llm",
    "router",
    "fallback",
    "quota",
    "ai-agents",
    "plugin"
  ],
  "files": [
    "bin",
    "src",
    "plugin",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "node --test test/*.test.js",
    "lint": "node --check src/index.js && node --check bin/ofs.js",
    "sync-models": "node scripts/sync-models.mjs"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/rustemmustafingovua-byte/opencode-free-stack.git"
  },
  "bugs": {
    "url": "https://github.com/rustemmustafingovua-byte/opencode-free-stack/issues"
  },
  "homepage": "https://github.com/rustemmustafingovua-byte/opencode-free-stack#readme",
  "dependencies": {
    "viem": "^2.57.7"
  },
  "funding": {
    "custom": [
      "https://github.com/sponsors/rustemmustafingovua-byte"
    ]
  }
}

{
  "$schema": "https://opencode.ai/config.json",
  "model": "apinex/free/qwen-3.8-max",
  "small_model": "apinex/free/deepseek-v4-flash-0731",
  "provider": {
    "apinex": {
      "npm": "@ai-sdk/openai-compatible",
      "name": "APInex (free)",
      "options": {
        "baseURL": "https://api.apinex.bond/v1",
        "apiKey": "{env:APINEX_API_KEY}",
        "maxRetries": 8,
        "setCacheKey": true
      },
      "whitelist": [
        "free/qwen-3.8-max",
        "free/deepseek-v4-pro-0813",
        "free/gemini-3.8-flash",
        "free/glm-5.3-flashx",
        "free/glm-5.3-flash",
        "free/deepseek-v4.1-flash",
        "free/deepseek-v4-flash-0731",
        "free/mimo-v2.6-pro",
        "free/glm-5.3"
      ],
      "models": {
        "free/qwen-3.8-max": { "name": "Qwen 3.8 MAX", "limit": { "context": 1000000, "output": 32000 }, "tool_call": true, "attachment": true, "cost": { "input": 0, "output": 0, "cache_read": 0, "cache_write": 0 } },
        "free/deepseek-v4-pro-0813": { "name": "Deepseek V4 Pro", "limit": { "context": 1000000, "output": 32000 }, "tool_call": true, "cost": { "input": 0, "output": 0, "cache_read": 0, "cache_write": 0 } },
        "free/gemini-3.8-flash": { "name": "Gemini 3.8 Flash", "limit": { "context": 1000000, "output": 32000 }, "tool_call": true, "attachment": true, "cost": { "input": 0, "output": 0, "cache_read": 0, "cache_write": 0 } },
        "free/glm-5.3-flashx": { "name": "GLM 5.3 FlashX", "limit": { "context": 1000000, "output": 32000 }, "tool_call": true, "attachment": true, "cost": { "input": 0, "output": 0, "cache_read": 0, "cache_write": 0 } },
        "free/glm-5.3-flash": { "name": "GLM-5.3 Flash", "limit": { "context": 1000000, "output": 32000 }, "tool_call": true, "attachment": true, "cost": { "input": 0, "output": 0, "cache_read": 0, "cache_write": 0 } },
        "free/deepseek-v4.1-flash": { "name": "Deepseek V4.1 Flash 1017", "limit": { "context": 1000000, "output": 32000 }, "tool_call": true, "attachment": true, "cost": { "input": 0, "output": 0, "cache_read": 0, "cache_write": 0 } },
        "free/deepseek-v4-flash-0731": { "name": "Deepseek V4 Flash", "limit": { "context": 1000000, "output": 32000 }, "tool_call": true, "cost": { "input": 0, "output": 0, "cache_read": 0, "cache_write": 0 } },
        "free/mimo-v2.6-pro": { "name": "Mimo V2.6 Pro", "limit": { "context": 1000000, "output": 32000 }, "tool_call": true, "cost": { "input": 0, "output": 0, "cache_read": 0, "cache_write": 0 } },
        "free/glm-5.3": { "name": "GLM 5.3", "limit": { "context": 1000000, "output": 32000 }, "tool_call": true, "cost": { "input": 0, "output": 0, "cache_read": 0, "cache_write": 0 } }
      }
    }
  }
}
